REALISM_VOCAB = (
    'resource_limited', 'novel_situation', 'dynamic_environment',
    'real_world_sourced', 'underspecified', 'real_time_coordination',
)

def realism_score(task):
    """Count of realism factors carried by this task record."""
    return len([f for f in task['realism_factors'] if f in REALISM_VOCAB])

def pass_rate_by_realism(tasks, results):
    """Pass rate SPLIT by realism score, never a bare aggregate."""
    buckets = {}
    for task, result in zip(tasks, results):
        buckets.setdefault(realism_score(task), []).append(result.passed)
    return {k: sum(v) / len(v) for k, v in buckets.items()}
